from collections import deque
def fill_enclosed(grid, fill=4):
    h,w=len(grid),len(grid[0])
    cnt=collections.Counter(v for row in grid for v in row)
    bg=cnt.most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]
    dq=deque()
    for i in range(h):
        for j in (0,w-1):
            if grid[i][j]==bg and not seen[i][j]: seen[i][j]=True; dq.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if grid[i][j]==bg and not seen[i][j]: seen[i][j]=True; dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and grid[ni][nj]==bg and not seen[ni][nj]:
                seen[ni][nj]=True; dq.append((ni,nj))
    return [[fill if grid[i][j]==bg and not seen[i][j] else v for j,v in enumerate(row)] for i,row in enumerate(grid)]
